-- RegistreAi reference data seed\n-- Generated from the live Supabase project. Contains no customer data or secrets.\n\nINSERT INTO public.plans(code,name,setup_fee_cents,monthly_fee_cents,unlimited_marks,resources_included,guarantee_included,active,public_description) VALUES ('ILIMITADO','Ilimitado',49700,59900,true,true,true,true,'Honorários de registros ilimitados para o mesmo CPF ou CNPJ titular do plano. Sem carência e cancelamento quando quiser. Não permite terceiros. Taxas oficiais do INPI à parte.') ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name,setup_fee_cents=EXCLUDED.setup_fee_cents,monthly_fee_cents=EXCLUDED.monthly_fee_cents,unlimited_marks=EXCLUDED.unlimited_marks,resources_included=EXCLUDED.resources_included,guarantee_included=EXCLUDED.guarantee_included,active=EXCLUDED.active,public_description=EXCLUDED.public_description;







-- Durable queues

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pgmq.list_queues() WHERE queue_name='reg_jobs') THEN PERFORM pgmq.create('reg_jobs'); END IF;
  IF NOT EXISTS (SELECT 1 FROM pgmq.list_queues() WHERE queue_name='notifications') THEN PERFORM pgmq.create('notifications'); END IF;
  IF NOT EXISTS (SELECT 1 FROM pgmq.list_queues() WHERE queue_name='inpi_jobs') THEN PERFORM pgmq.create('inpi_jobs'); END IF;
  IF NOT EXISTS (SELECT 1 FROM pgmq.list_queues() WHERE queue_name='legal_jobs') THEN PERFORM pgmq.create('legal_jobs'); END IF;
END $$;

-- Private storage bucket
VALUES ('registreai-private','registreai-private',false,52428800,ARRAY['application/pdf','image/jpeg','image/png','image/webp','application/vnd.openxmlformats-officedocument.wordprocessingml.document'])
ON CONFLICT (id) DO UPDATE SET public=false,file_size_limit=EXCLUDED.file_size_limit,allowed_mime_types=EXCLUDED.allowed_mime_types;

-- Scheduled jobs
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname='registreai_rpi_poll') THEN
    PERFORM cron.schedule('registreai_rpi_poll','17 */6 * * *', $cmd$select pgmq.send(''inpi_jobs'',''{"job_type":"rpi_poll"}''::jsonb,0);$cmd$);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname='registreai_deadline_sweep') THEN
    PERFORM cron.schedule('registreai_deadline_sweep','11 * * * *', $cmd$select pgmq.send(''legal_jobs'',''{"job_type":"deadline_sweep"}''::jsonb,0);$cmd$);
  END IF;
END $$;
